def thanos_sort_max_length(n, arr):
    def max_sorted_subarray(arr):
        length = len(arr)
        dp = [1] * length
        for i in range(1, length):
            if arr[i] >= arr[i - 1]:
                dp[i] = dp[i - 1] + 1
        return max(dp)

    while n > 1:
        mid = n // 2
        left_half = arr[:mid]
        right_half = arr[mid:]
        left_max = max_sorted_subarray(left_half)
        right_max = max_sorted_subarray(right_half)
        if left_max == mid or right_max == mid:
            break
        if left_max > right_max:
            arr = left_half
        else:
            arr = right_half
        n = mid
    return max_sorted_subarray(arr)

