    n = len(arr)

    def is_sorted(subarr):
        return all(subarr[i] <= subarr[i + 1] for i in range(len(subarr) - 1))

    def max_length_recursive(start, end):
        if start == end:
            return 1
        mid = (start + end) // 2
        left_max = max_length_recursive(start, mid)
        right_max = max_length_recursive(mid + 1, end)

        combined_left = arr[start:mid + 1]
        combined_right = arr[mid + 1:end + 1]

        if is_sorted(combined_left) and is_sorted(combined_right):
            return mid - start + 1 + right_max
        elif is_sorted(combined_left):
            return left_max
        elif is_sorted(combined_right):
            return right_max
        else:
            return 1

    return max_length_recursive(0, n - 1)

